const triggerData = $('When chat message received').first().json;
const userMsg = (triggerData.chatInput || '').toLowerCase();
let output = $input.first().json.output || '';

// 1. Kişisel sağlık verisi / şikayet tespiti
const healthDataKeywords = [
  'ağrı', 'agrı', 'sızı', 'kanama', 'kanıyor', 'şiş', 'iltihap', 'apse',
  'çürük', 'curuk', 'röntgen', 'rontgen', 'tedavi', 'ilaç', 'ilac',
  'antibiyotik', 'diyabet', 'şeker hastal', 'hamile', 'gebe', 'bende',
  'dişim', 'disim', 'diş etim', 'ağzım', 'agzim', 'çenem', 'cenem',
  'dilim', 'damağım', 'dudağım', 'tat', 'koku', 'hassas', 'yara', 'leke',
  'kuruluk', 'uyuşma', 'yaşındayım', 'hastalığım', 'ameliyat',
  'çekim', 'dolgu', 'kanal', 'şikayet', 'kırıldı', 'sallanıyor', 'periodontitis',
  'gingivitis', 'bruksizm', 'tahlil', 'rapor', 'hissediyorum'
];

const hasPersonalHealthData = healthDataKeywords.some(kw => userMsg.includes(kw));
const hasKvkkLink = output.toLowerCase().includes('kvkk');

if (hasPersonalHealthData && !hasKvkkLink) {
  output += '\n\n---\n📄 **Kişisel Verilerin Korunması (KVKK):** Paylaştığınız sağlık bilgileri hakkında [KVKK Aydınlatma Metni](http://localhost:5678/webhook/kvkk) belgesini inceleyebilirsiniz.';
}

// 2. Acil durum tespiti
const emergencyKeywords = [
  'durmayan kanama', 'çok kanıyor', 'dişim kırıldı', 'yerinden çıktı',
  'yüzüm şişti', 'nefes', 'yutma güçlüğü', 'çene kırığı'
];
const isEmergency = emergencyKeywords.some(kw => userMsg.includes(kw));
if (isEmergency && !output.includes('112')) {
  output += '\n\n⚠️ **Acil Durum Uyarısı:** Şiddetli kanama, travma veya yüzde yaygın şişlik gibi acil durumlarda vakit kaybetmeden en yakın acil diş polikliniğine veya **112 Acil**\'e başvurunuz.';
}

return [{ json: { output } }];
